data.query:
query Load($where: LoadWhereInput, $orderBy: [LoadOrderByInput!], $first: Int, $after: String) {
  load(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
        shipments {
          edges {
            node {
              id
              number
              shipmentLines {
                edges {
                  node {
                    id
                    number
                    quantity {
                      value
                      unitId
                    }
                    packedQuantity {
                      value
                      unitId
                    }
                    orderLineRelease {
                      id
                      number
                      quantity {
                        value
                        unitId
                      }
                      quantityLeft {
                        value
                        unitId
                      }
                      pickSteps {
                        edges {
                          node {
                            pickId
                            id
                            pickStepStatusId
                            quantity {
                              value
                              unitId
                            }
                            inventoryPickSteps {
                              edges {
                                node {
                                  id
                                  picked
                                  pickedAt
                                  packedAt
                                  allocatedQuantity {
                                    value
                                    unitId
                                  }
                                }
                              }
                            }
                          }
                        }
                      }
                      orderLine {
                        product {
                          number
                          description
                        }
                        order {
                          id
                          number
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

branches.transform:
$count($filter($.load.edges.node.shipments.edges.node.shipmentLines.edges.node, function($sl) {
  $sl.orderLineRelease != null and (
    $sl.packedQuantity = null or
    $sl.packedQuantity.value < $sl.orderLineRelease.quantity.value or
    $count($filter($sl.orderLineRelease.pickSteps.edges.node.inventoryPickSteps.edges.node, function($ips) {
      $ips.packedAt = null
    })) > 0
  )
})) > 0

$count($filter($.load.edges.node.shipments.edges.node.shipmentLines.edges.node, function($sl) {
  $sl.orderLineRelease != null and
  $sl.orderLineRelease.allowOverage != true and
  $sl.packedQuantity != null and
  $sl.packedQuantity.value > $sl.orderLineRelease.quantity.value
})) > 0

data.messageTransform:
(
  $shipmentLines := $.load.edges.node.shipments.edges.node.shipmentLines.edges.node;
  $unpicked := $filter($shipmentLines, function($sl) {
    $sl.orderLineRelease != null and
    $count($filter($sl.orderLineRelease.pickSteps.edges.node.inventoryPickSteps.edges.node, function($ips) {
      $ips.picked != true
    })) > 0
  });

  "The following products have not been fully picked:\n" & $join($map($unpicked, function($sl) {
    "Order: " & $sl.orderLineRelease.orderLine.order.number & " | " & "Product: " & $sl.orderLineRelease.orderLine.product.number & ($sl.orderLineRelease.orderLine.product.description ? " (" & $sl.orderLineRelease.orderLine.product.description & ")" : "") & " | Ordered: " & $sl.orderLineRelease.quantity.value & " " & $sl.orderLineRelease.quantity.unitId
  }), "\n")
)

(
  $shipmentLines := $.load.edges.node.shipments.edges.node.shipmentLines.edges.node;
  $incomplete := $filter($shipmentLines, function($sl) {
    $sl.orderLineRelease != null and (
      $sl.packedQuantity = null or
      $sl.packedQuantity.value < $sl.orderLineRelease.quantity.value or
      $count($filter($sl.orderLineRelease.pickSteps.edges.node.inventoryPickSteps.edges.node, function($ips) {
        $ips.packedAt = null
      })) > 0
    )
  });

  "The following products have not been fully packed:\n" & $join($map($incomplete, function($sl) {
    "Order: " & $sl.orderLineRelease.orderLine.order.number & " | " & "Product: " & $sl.orderLineRelease.orderLine.product.number & ($sl.orderLineRelease.orderLine.product.description ? " (" & $sl.orderLineRelease.orderLine.product.description & ")" : "") & " | Ordered: " & $sl.orderLineRelease.quantity.value & " " & $sl.orderLineRelease.quantity.unitId & " | Packed: " & ($sl.packedQuantity.value ? $sl.packedQuantity.value : 0) & " " & $sl.orderLineRelease.quantity.unitId
  }), "\n")
)

(
  $shipmentLines := $.load.edges.node.shipments.edges.node.shipmentLines.edges.node;
  $over := $filter($shipmentLines, function($sl) {
    $sl.orderLineRelease != null and
    $sl.orderLineRelease.allowOverage = false and
    $sl.packedQuantity != null and
    $sl.packedQuantity.value > $sl.orderLineRelease.quantity.value
  });

  "The following products have been packed over the ordered quantity:\n" & $join($map($over, function($sl) {
    "Order " & $sl.orderLineRelease.orderLine.order.number & " | " & $sl.orderLineRelease.orderLine.product.number & ($sl.orderLineRelease.orderLine.product.description ? " (" & $sl.orderLineRelease.orderLine.product.description & ")" : "") & " | Ordered: " & $sl.orderLineRelease.quantity.value & " " & $sl.orderLineRelease.quantity.unitId & " | Packed: " & $sl.packedQuantity.value & " " & $sl.packedQuantity.unitId
  }), "\n")
)

(
  $shipmentLines := $.load.edges.node.shipments.edges.node.shipmentLines.edges.node;
  $missing := $filter($shipmentLines, function($sl) {
    $sl.orderLineRelease != null and
    $count($sl.orderLineRelease.pickSteps.edges) = 0
  });

  "The following products have no pick steps assigned:\n" & $join($map($missing, function($sl) {
    "Order " & $sl.orderLineRelease.orderLine.order.number & " | " & $sl.orderLineRelease.orderLine.product.number & ($sl.orderLineRelease.orderLine.product.description ? " (" & $sl.orderLineRelease.orderLine.product.description & ")" : "") & " | Ordered: " & $sl.orderLineRelease.quantity.value & " " & $sl.orderLineRelease.quantity.unitId
  }), "\n") & "\n\nWould you like to add the pick steps now?"
)

